-- Paket 13.11.2026 (2): quantity buttons in catalogue cards on phones (new chunk HtsListQty, template 18). Text is hex-encoded on purpose.
SET NAMES utf8mb4;
SET SESSION group_concat_max_len = 100000;
-- APPLY. Saves the template to hts_bak_20261113_qty first; safe to run twice.
CREATE TABLE IF NOT EXISTS hts_bak_20261113_qty (kind VARCHAR(16) NOT NULL, el_id INT NOT NULL, body MEDIUMTEXT, saved_at DATETIME NOT NULL, PRIMARY KEY (kind, el_id)) DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO hts_bak_20261113_qty (kind, el_id, body, saved_at) SELECT 'template', t.id, t.content, NOW() FROM modx_site_templates t WHERE t.id = 18 AND t.content NOT LIKE '%[[$HtsListQty]]%';
UPDATE modx_site_templates t SET t.content = REPLACE(CONVERT(t.content USING utf8mb4), _utf8mb4 0x5B5B244874734D6F62696C6546696C746572735D5D, _utf8mb4 0x5B5B244874734D6F62696C6546696C746572735D5D0A2020202020202020202020202020202020202020202020205B5B244874734C6973745174795D5D)
WHERE t.id = 18 AND t.templatename = _utf8mb4 0xD09FD0BED0B4D0BAD0B0D182D0B5D0B3D0BED180D0B8D18F AND t.content NOT LIKE '%[[$HtsListQty]]%' AND ROUND((CHAR_LENGTH(CONVERT(t.content USING utf8mb4)) - CHAR_LENGTH(REPLACE(CONVERT(t.content USING utf8mb4), _utf8mb4 0x5B5B244874734D6F62696C6546696C746572735D5D, ''))) / 21) = 1;
INSERT INTO modx_site_htmlsnippets (source, name, description, category, snippet, properties, static, static_file)
SELECT 1, 'HtsListQty', _utf8mb4 0xD09AD0BDD0BED0BFD0BAD0B820C2ABE28892C2BB20D0B820C2AB2BC2BB20D0B220D0BAD0B0D180D182D0BED187D0BAD0B0D18520D0BAD0B0D182D0B0D0BBD0BED0B3D0B020D0BDD0B020D182D0B5D0BBD0B5D184D0BED0BDD0B5, 0, _utf8mb4 , 'a:0:{}', 0, '' FROM (SELECT 1 AS x) d
WHERE NOT EXISTS (SELECT 1 FROM modx_site_htmlsnippets WHERE name = 'HtsListQty');
-- RESULT: expect 2 x DONE.
SELECT itog, COUNT(*) AS n, GROUP_CONCAT(chto ORDER BY chto SEPARATOR '; ') AS what FROM (
SELECT _utf8mb4 0x312E20D0A8D0B0D0B1D0BBD0BED0BD20C2ABD09FD0BED0B4D0BAD0B0D182D0B5D0B3D0BED180D0B8D18FC2BB2028313829 AS chto, CASE WHEN t.id IS NULL THEN _utf8mb4 0xD09DD09520D0A1D09ED092D09FD090D094D090D095D0A220E2809420D181D182D0BED0BF2C20D181D0BAD180D0B8D0BDD188D0BED182 WHEN t.content LIKE '%[[$HtsListQty]]%' THEN _utf8mb4 0xD0A3D096D09520D09FD095D0A0D095D09DD095D0A1D095D09DD09E WHEN ROUND((CHAR_LENGTH(CONVERT(t.content USING utf8mb4)) - CHAR_LENGTH(REPLACE(CONVERT(t.content USING utf8mb4), _utf8mb4 0x5B5B244874734D6F62696C6546696C746572735D5D, ''))) / 21) = 1 THEN _utf8mb4 0xD0A1D09ED092D09FD090D094D090D095D0A220E2809420D0BCD0BED0B6D0BDD0BE20D0BFD0B5D180D0B5D0BDD0BED181D0B8D182D18C ELSE _utf8mb4 0xD09DD09520D0A1D09ED092D09FD090D094D090D095D0A220E2809420D181D182D0BED0BF2C20D181D0BAD180D0B8D0BDD188D0BED182 END AS itog
FROM (SELECT 1 AS x) d LEFT JOIN modx_site_templates t ON t.id = 18 AND t.templatename = _utf8mb4 0xD09FD0BED0B4D0BAD0B0D182D0B5D0B3D0BED180D0B8D18F
UNION ALL
SELECT _utf8mb4 0x322E20D09DD0BED0B2D18BD0B920D187D0B0D0BDD0BA204874734C697374517479, CASE WHEN (SELECT COUNT(*) FROM modx_site_htmlsnippets WHERE name = 'HtsListQty') = 0 THEN _utf8mb4 0xD0A1D09ED092D09FD090D094D090D095D0A220E2809420D0BCD0BED0B6D0BDD0BE20D0BFD0B5D180D0B5D0BDD0BED181D0B8D182D18C ELSE _utf8mb4 0xD0A3D096D09520D09FD095D0A0D095D09DD095D0A1D095D09DD09E END
) q GROUP BY itog;
